//! The Exabeam catalogue, compiled in and parsed once per process.
//!
//! `catalogs/exabeam/` is generated by `scripts/sync_exabeam_catalog.py` from
//! ExabeamLabs/CIMLibrary (Apache-2.0): the Common Information Model's fields
//! with their types, the platform fields the CIM table omits, and the
//! subjects, activity types and outcomes. Fields come from the tenant's
//! parsers too, so the catalogue never makes an error: an unknown field is
//! the warning `exabeam_unknown_field` (exabeam-1.0, "Field catalogue").

use serde::Deserialize;
use std::collections::HashMap;
use std::sync::OnceLock;

const FIELDS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/exabeam/fields.toml"
));
const VALUES_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/exabeam/values.toml"
));

/// The CIM data type of a field, as far as the checks need it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FieldKind {
    String,
    Number,
    Boolean,
    Datetime,
    Ip,
    Other,
}

/// One field (`src_ip`, `activity_type`, `approxLogTime`).
#[derive(Debug, Clone, Deserialize)]
pub struct Field {
    pub name: String,
    /// The CIM type: `string`, `integer`, `number`, `boolean`, `datetime`,
    /// `ipv4/ipv6`, `array`, `hexadecimal`, `email`, `json`.
    #[serde(rename = "type")]
    pub ty: String,
    pub description: String,
    /// A platform field the CIM table does not list.
    #[serde(default)]
    pub platform: bool,
}

impl Field {
    pub fn kind(&self) -> FieldKind {
        match self.ty.as_str() {
            "string" => FieldKind::String,
            "integer" | "number" => FieldKind::Number,
            "boolean" => FieldKind::Boolean,
            "datetime" => FieldKind::Datetime,
            "ipv4/ipv6" => FieldKind::Ip,
            _ => FieldKind::Other,
        }
    }
}

/// A field-name prefix that is never unknown (`c_`, `m_`).
#[derive(Debug, Clone, Deserialize)]
pub struct Prefix {
    pub prefix: String,
    pub description: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Subject {
    pub name: String,
    #[serde(default)]
    pub description: String,
}

/// An activity type, `<subject>-<activity>` (`process-create`).
#[derive(Debug, Clone, Deserialize)]
pub struct ActivityType {
    pub name: String,
    pub subject: String,
    pub activity: String,
    #[serde(default)]
    pub pretty_name: String,
    #[serde(default)]
    pub outcomes: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct FieldsFile {
    #[serde(default)]
    prefixes: Vec<Prefix>,
    #[serde(default)]
    fields: Vec<Field>,
}

#[derive(Debug, Deserialize)]
struct ValuesFile {
    #[serde(default)]
    outcomes: Vec<String>,
    #[serde(default)]
    subjects: Vec<Subject>,
    #[serde(default)]
    activity_types: Vec<ActivityType>,
}

#[derive(Debug)]
pub struct Catalog {
    pub fields: Vec<Field>,
    pub prefixes: Vec<Prefix>,
    pub subjects: Vec<Subject>,
    pub activity_types: Vec<ActivityType>,
    pub outcomes: Vec<String>,
    by_name: HashMap<String, usize>,
}

impl Catalog {
    pub fn cached() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            let fields: FieldsFile =
                toml::from_str(FIELDS_TOML).expect("catalogs/exabeam/fields.toml");
            let values: ValuesFile =
                toml::from_str(VALUES_TOML).expect("catalogs/exabeam/values.toml");
            let by_name = fields
                .fields
                .iter()
                .enumerate()
                .map(|(i, f)| (f.name.to_lowercase(), i))
                .collect();
            Catalog {
                fields: fields.fields,
                prefixes: fields.prefixes,
                subjects: values.subjects,
                activity_types: values.activity_types,
                outcomes: values.outcomes,
                by_name,
            }
        })
    }

    /// The field named `name`, compared without regard to case (the engine
    /// compares field names case-insensitively, exabeam-1.0).
    pub fn field(&self, name: &str) -> Option<&Field> {
        self.by_name
            .get(&name.to_lowercase())
            .map(|&i| &self.fields[i])
    }

    /// The prefix `name` starts with, if it is a custom or metadata field.
    pub fn prefix(&self, name: &str) -> Option<&Prefix> {
        let lower = name.to_lowercase();
        self.prefixes.iter().find(|p| lower.starts_with(&p.prefix))
    }

    /// Whether `name` is a field the catalogue knows: a CIM or platform field,
    /// a `c_` or `m_` field, or a part of a structured field whose first part
    /// is known (`geo_src_ip.country`).
    pub fn knows(&self, name: &str) -> bool {
        if self.field(name).is_some() || self.prefix(name).is_some() {
            return true;
        }
        name.split_once('.')
            .is_some_and(|(head, _)| self.field(head).is_some() || self.prefix(head).is_some())
    }

    /// A known field one edit (two for names of 12 characters or more) from
    /// `name`, for the warning's message.
    pub fn suggest(&self, name: &str) -> Option<&str> {
        let lower = name.to_lowercase();
        let limit = if lower.chars().count() >= 12 { 2 } else { 1 };
        self.fields
            .iter()
            .filter_map(|f| {
                let d = edit_distance(&lower, &f.name.to_lowercase(), limit)?;
                Some((d, f.name.as_str()))
            })
            .min_by_key(|(d, _)| *d)
            .map(|(_, n)| n)
    }

    pub fn subject(&self, name: &str) -> Option<&Subject> {
        self.subjects
            .iter()
            .find(|s| s.name.eq_ignore_ascii_case(name))
    }

    pub fn activity_type(&self, name: &str) -> Option<&ActivityType> {
        self.activity_types
            .iter()
            .find(|a| a.name.eq_ignore_ascii_case(name))
    }
}

/// Levenshtein distance between `a` and `b`, or `None` when it exceeds
/// `limit`.
fn edit_distance(a: &str, b: &str, limit: usize) -> Option<usize> {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.len().abs_diff(b.len()) > limit {
        return None;
    }
    let mut previous: Vec<usize> = (0..=b.len()).collect();
    for (i, ca) in a.iter().enumerate() {
        let mut current = vec![i + 1; b.len() + 1];
        for (j, cb) in b.iter().enumerate() {
            let cost = usize::from(ca != cb);
            current[j + 1] = (previous[j] + cost)
                .min(previous[j + 1] + 1)
                .min(current[j] + 1);
        }
        if current.iter().min().copied().unwrap_or(0) > limit {
            return None;
        }
        previous = current;
    }
    let d = previous[b.len()];
    (d <= limit).then_some(d)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalogue_loads_the_cim_and_the_platform_fields() {
        let c = Catalog::cached();
        assert!(c.fields.len() >= 1130, "{}", c.fields.len());
        assert_eq!(c.field("src_ip").map(Field::kind), Some(FieldKind::Ip));
        assert_eq!(
            c.field("event_code").map(Field::kind),
            Some(FieldKind::String)
        );
        assert_eq!(
            c.field("dest_port").map(Field::kind),
            Some(FieldKind::Number)
        );
        for platform in [
            "approxLogTime",
            "rawLogIds",
            "ingest_time",
            "raw_log_time",
            "time",
        ] {
            assert!(c.field(platform).is_some(), "{platform}");
        }
        assert!(c.field("APPROXLOGTIME").is_some());
        assert!(c.knows("c_anything"));
        assert!(c.knows("m_anything"));
        assert!(!c.knows("ScriptBlockText"));
        assert_eq!(c.subjects.len(), 84);
        assert_eq!(c.activity_types.len(), 456);
        assert_eq!(c.outcomes, ["fail", "success"]);
        assert!(c.activity_type("process-create").is_some());
    }

    #[test]
    fn near_misses_are_suggested() {
        let c = Catalog::cached();
        assert_eq!(c.suggest("src_ipp"), Some("src_ip"));
        assert_eq!(c.suggest("zzzzzzzz"), None);
    }
}
